## 数据写入规范

所有持久化操作必须通过 `DataBridge.forward()`：

```typescript
import { DataBridge } from '@/core/databridge'
import type { Envelope } from '@/core/envelope'

const envelope: Envelope<YourType> = {
  /* ... */
}
await DataBridge.forward('routeName', envelope)
```

## withBroadcast 规范

使用项目提供的 `withBroadcast` 包装 Store：

```typescript
import { create } from 'zustand'
import { withBroadcast } from '@/store/helpers/withBroadcast'
import type { YourState, YourActions } from '@/types/modules/your.types'

interface YourStore extends YourState, YourActions {}

export const useYourStore = create<YourStore>()(
  withBroadcast(
    (set, get) => ({
      // state
      // actions
    }),
    { channel: 'your-store-channel' }
  )
)
```
